1	import type { SqliteClient } from "@effect/sql-sqlite-do";
2	import {
3	  authorizeRoundAction,
4	  emailLocaleOf,
5	  hashToken,
6	  JobId,
7	  nextEightWeeksCadenceDates,
8	  type PersonId,
9	  roundCommandRejection,
10	  type RoundCommand,
11	  type RoundCommandResult,
12	  SendId,
13	  type makeSendStore,
14	  type TransactionalEmail,
15	  type InvitationTokenRef,
16	} from "@surveybeat/domain";
17	import * as Effect from "effect/Effect";
18	import type { makeSqlActions } from "../SqlActions.ts";
19	import type { makeSqlDirectory } from "../SqlDirectory.ts";
20	import type { makeSqlPulses } from "../SqlPulses.ts";
21	import type { makeSqlRounds } from "../SqlRounds.ts";
22	import { firstRatingQuestionOf, type makeRoundJobs, reviewEndsAtOf } from "./RoundJobs.ts";
23	import type { makeScheduling } from "./Scheduling.ts";
24	
25	export const organizationRoundCommands = ({
26	  sql,
27	  rounds,
28	  directory,
29	  pulses,
30	  actions,
31	  sends,
32	  scheduling,
33	  jobs,
34	  repairAlarm,
35	  randomId,
36	  tokenOf,
37	  appOrigin,
38	}: {
39	  sql: SqliteClient.SqliteClient;
40	  rounds: ReturnType<typeof makeSqlRounds>;
41	  directory: ReturnType<typeof makeSqlDirectory>;
42	  pulses: ReturnType<typeof makeSqlPulses>;
43	  actions: ReturnType<typeof makeSqlActions>;
44	  sends: ReturnType<typeof makeSendStore>;
45	  scheduling: ReturnType<typeof makeScheduling>;
46	  jobs: ReturnType<typeof makeRoundJobs>;
47	  repairAlarm: () => Effect.Effect<void>;
48	  randomId: () => string;
49	  tokenOf: (ref: InvitationTokenRef) => Effect.Effect<string>;
50	  appOrigin: string;
51	}) => {
52	  const both = Effect.all([directory.load, pulses.load]);
53	  const { scheduleNextRound } = scheduling;
54	  const { executeComputeJob, shareResults } = jobs;
55	
56	  return {
57	    runRoundCommand: (actorId: PersonId, command: RoundCommand, now: number) =>
58	      sql
59	        .withTransaction(
60	          Effect.gen(function* () {
61	            const [dirState, pulseState] = yield* both;
62	            const auth = authorizeRoundAction(dirState, actorId, "team.manageRounds", command.teamId);
63	            if (auth._tag === "Rejected") return auth satisfies RoundCommandResult;
64	
65	            switch (command._tag) {
66	              case "SkipWeek": {
67	                const team = dirState.teams.find((t) => t.id === command.teamId);
68	                const pulse = pulseState.pulses.find((p) => p.id === command.pulseId);
69	                if (team === undefined) {
70	                  return {
71	                    _tag: "Rejected",
72	                    rejection: { _tag: "TeamNotFound" },
73	                  } satisfies RoundCommandResult;
74	                }
75	                if (pulse === undefined) {
76	                  return {
77	                    _tag: "Rejected",
78	                    rejection: { _tag: "PulseNotFound" },
79	                  } satisfies RoundCommandResult;
80	                }
81	
82	                const validWeeks = nextEightWeeksCadenceDates(now, pulse.settings.cadence.day, team.timeZone);
83	                if (!validWeeks.includes(command.plannedOpenDate)) {
84	                  return {
85	                    _tag: "Rejected",
86	                    rejection: { _tag: "WeekOutOfRange" },
87	                  } satisfies RoundCommandResult;
88	                }
89	
90	                yield* rounds.skipWeek(command.pulseId, command.plannedOpenDate, now);
91	                const scheduled = yield* rounds.findScheduledRound(command.pulseId);
92	                if (scheduled !== null && scheduled.plannedOpenDate === command.plannedOpenDate) {
93	                  yield* rounds.cancelRound(scheduled.id, now);
94	                  yield* rounds.cancelJobsForRound(scheduled.id);
95	                  yield* scheduleNextRound(command.pulseId, command.teamId, now);
96	                }
97	                yield* repairAlarm();
98	                return { _tag: "Accepted" } satisfies RoundCommandResult;
99	              }
100	
101	              case "UnskipWeek": {
102	                yield* rounds.unskipWeek(command.pulseId, command.plannedOpenDate);
103	                const scheduled = yield* rounds.findScheduledRound(command.pulseId);
104	                const open = yield* rounds.findOpenRound(command.pulseId);
105	                if (scheduled === null && open === null) {
106	                  yield* scheduleNextRound(command.pulseId, command.teamId, now);
107	                }
108	                yield* repairAlarm();
109	                return { _tag: "Accepted" } satisfies RoundCommandResult;
110	              }
111	
112	              case "PausePulse": {
113	                yield* rounds.pausePulse(command.pulseId, now);
114	                const scheduled = yield* rounds.findScheduledRound(command.pulseId);
115	                if (scheduled !== null) {
116	                  yield* rounds.cancelRound(scheduled.id, now);
117	                  yield* rounds.cancelJobsForRound(scheduled.id);
118	                }
119	                yield* repairAlarm();
120	                return { _tag: "Accepted" } satisfies RoundCommandResult;
121	              }
122	
123	              case "ResumePulse": {
124	                yield* rounds.resumePulse(command.pulseId);
125	                const scheduled = yield* rounds.findScheduledRound(command.pulseId);
126	                const open = yield* rounds.findOpenRound(command.pulseId);
127	                if (scheduled === null && open === null) {
128	                  yield* scheduleNextRound(command.pulseId, command.teamId, now);
129	                }
130	                yield* repairAlarm();
131	                return { _tag: "Accepted" } satisfies RoundCommandResult;
132	              }
133	
134	              case "CloseRoundEarly": {
135	                const round = yield* rounds.getRound(command.roundId);
136	                if (round === null || round.teamId !== command.teamId) {
137	                  return {
138	                    _tag: "Rejected",
139	                    rejection: { _tag: "RoundNotFound" },
140	                  } satisfies RoundCommandResult;
141	                }
142	                const rejection = roundCommandRejection(round.status, command);
143	                if (rejection !== null) {
144	                  return { _tag: "Rejected", rejection } satisfies RoundCommandResult;
145	                }
146	
147	                const effectiveN = Math.max(
148	                  dirState.minimumGroupSize,
149	                  round.effectiveMinimumGroupSize ?? dirState.minimumGroupSize,
150	                );
151	                yield* rounds.closeRound(
152	                  round.id,
153	                  now,
154	                  effectiveN,
155	                  reviewEndsAtOf(pulseState, round.pulseId, now),
156	                );
157	                yield* rounds.cancelJobsForRound(round.id, ["send", "remind", "close"]);
158	
159	                const computeJobId = JobId.make(randomId());
160	                yield* rounds.insertJob({
161	                  id: computeJobId,
162	                  roundId: round.id,
163	                  type: "compute",
164	                  dueAt: now,
165	                  status: "pending",
166	                  payload: null,
167	                  createdAt: now,
168	                  completedAt: null,
169	                });
170	                yield* executeComputeJob(computeJobId, round.id, now);
171	                yield* repairAlarm();
172	                return { _tag: "Accepted" } satisfies RoundCommandResult;
173	              }
174	
175	              case "ShareResults": {
176	                const round = yield* rounds.getRound(command.roundId);
177	                if (round === null || round.teamId !== command.teamId) {
178	                  return {
179	                    _tag: "Rejected",
180	                    rejection: { _tag: "RoundNotFound" },
181	                  } satisfies RoundCommandResult;
182	                }
183	                if (auth.actor.roles.get(command.teamId) !== "lead") {
184	                  return {
185	                    _tag: "Rejected",
186	                    rejection: { _tag: "Forbidden" },
187	                  } satisfies RoundCommandResult;
188	                }
189	                if (round.status === "shared") {
190	                  return { _tag: "Accepted" } satisfies RoundCommandResult;
191	                }
192	                const rejection = roundCommandRejection(round.status, command);
193	                if (rejection !== null) {
194	                  return { _tag: "Rejected", rejection } satisfies RoundCommandResult;
195	                }
196	
197	                yield* shareResults(round.id, now);
198	                return { _tag: "Accepted" } satisfies RoundCommandResult;
199	              }
200	
201	              case "RetryResult": {
202	                const round = yield* rounds.getRound(command.roundId);
203	                if (round === null || round.teamId !== command.teamId) {
204	                  return {
205	                    _tag: "Rejected",
206	                    rejection: { _tag: "RoundNotFound" },
207	                  } satisfies RoundCommandResult;
208	                }
209	                if (auth.actor.roles.get(command.teamId) !== "lead") {
210	                  return {
211	                    _tag: "Rejected",
212	                    rejection: { _tag: "Forbidden" },
213	                  } satisfies RoundCommandResult;
214	                }
215	                if (round.status === "ready" || round.status === "shared") {
216	                  return { _tag: "Accepted" } satisfies RoundCommandResult;
217	                }
218	                const rejection = roundCommandRejection(round.status, command);
219	                if (rejection !== null) {
220	                  return { _tag: "Rejected", rejection } satisfies RoundCommandResult;
221	                }
222	                if (yield* rounds.hasPendingJob(round.id, "compute")) {
223	                  return { _tag: "Accepted" } satisfies RoundCommandResult;
224	                }
225	
226	                yield* rounds.deleteRoundResult(round.id);
227	                const computeJobId = JobId.make(randomId());
228	                yield* rounds.insertJob({
229	                  id: computeJobId,
230	                  roundId: round.id,
231	                  type: "compute",
232	                  dueAt: now,
233	                  status: "pending",
234	                  payload: null,
235	                  createdAt: now,
236	                  completedAt: null,
237	                });
238	                yield* executeComputeJob(computeJobId, round.id, now);
239	                yield* repairAlarm();
240	                return { _tag: "Accepted" } satisfies RoundCommandResult;
241	              }
242	
243	              case "CancelRound": {
244	                const round = yield* rounds.getRound(command.roundId);
245	                if (round === null || round.teamId !== command.teamId) {
246	                  return {
247	                    _tag: "Rejected",
248	                    rejection: { _tag: "RoundNotFound" },
249	                  } satisfies RoundCommandResult;
250	                }
251	                const rejection = roundCommandRejection(round.status, command);
252	                if (rejection !== null) {
253	                  return { _tag: "Rejected", rejection } satisfies RoundCommandResult;
254	                }
255	
256	                yield* rounds.cancelRound(round.id, now);
257	                yield* rounds.cancelJobsForRound(round.id);
258	                yield* rounds.revokeInvitationsForRound(round.id, now);
259	                yield* rounds.deleteSubmissionsAndParticipations(round.id);
260	                yield* repairAlarm();
261	                return { _tag: "Accepted" } satisfies RoundCommandResult;
262	              }
263	
264	              case "ResendInvitation": {
265	                const round = yield* rounds.getRound(command.roundId);
266	                if (round === null || round.teamId !== command.teamId) {
267	                  return {
268	                    _tag: "Rejected",
269	                    rejection: { _tag: "RoundNotFound" },
270	                  } satisfies RoundCommandResult;
271	                }
272	                const rejection = roundCommandRejection(round.status, command);
273	                if (rejection !== null) {
274	                  return { _tag: "Rejected", rejection } satisfies RoundCommandResult;
275	                }
276	
277	                const inv = yield* rounds.getInvitation(command.roundId, command.personId);
278	                if (inv === null) {
279	                  return {
280	                    _tag: "Rejected",
281	                    rejection: { _tag: "InvitationNotFound" },
282	                  } satisfies RoundCommandResult;
283	                }
284	
285	                const [dirState, pulseState] = yield* both;
286	                const person = dirState.people.find((p) => p.id === command.personId);
287	                if (person === undefined || person.removedAt !== null) {
288	                  return {
289	                    _tag: "Rejected",
290	                    rejection: { _tag: "InvitationNotFound" },
291	                  } satisfies RoundCommandResult;
292	                }
293	
294	                const pulse = pulseState.pulses.find((p) => p.id === round.pulseId);
295	                if (pulse === undefined) {
296	                  return {
297	                    _tag: "Rejected",
298	                    rejection: { _tag: "PulseNotFound" },
299	                  } satisfies RoundCommandResult;
300	                }
301	
302	                const invitation = {
303	                  roundId: command.roundId,
304	                  personId: command.personId,
305	                  generation: inv.resendCount + 1,
306	                };
307	                const newTokenHash = yield* tokenOf(invitation).pipe(
308	                  Effect.flatMap((token) => Effect.promise(() => hashToken(token))),
309	                );
310	                const newSendId = SendId.make(randomId());
311	                yield* rounds.resendInvitation(
312	                  command.roundId,
313	                  command.personId,
314	                  newSendId,
315	                  newTokenHash,
316	                  now,
317	                );
318	
319	                const ratingQuestion = firstRatingQuestionOf(pulse, pulseState);
320	                const eligibleActions = yield* actions.getEligibleActionsForRound(
321	                  round.teamId,
322	                  round.pulseId,
323	                  round.plannedOpenAt,
324	                );
325	
326	                const invitationEmail: TransactionalEmail = {
327	                  _tag: "InvitationEmail",
328	                  locale: emailLocaleOf(dirState, person.id),
329	                  pulseName: pulse.settings.name,
330	                  minimumGroupSize: dirState.minimumGroupSize,
331	                  invitation,
332	                  baseUrl: appOrigin,
333	                  ratingQuestion,
334	                  actions: eligibleActions.slice(0, 3).map((a) => a.title),
335	                  aiProcessing: dirState.aiProcessing,
336	                };
337	
338	                yield* sends.create(newSendId, person.email, invitationEmail);
339	                return { _tag: "Accepted" } satisfies RoundCommandResult;
340	              }
341	            }
342	          }),
343	        )
344	        .pipe(Effect.orDie),
345	  };
346	};
