export const localToUtc = (
  year: number,
  month: number,
  day: number,
  hour: number,
  minute: number,
  timeZone: string,
): number =>
  DateTime.toEpochMillis(
    DateTime.makeZonedUnsafe(
      { year, month, day, hour, minute },
      { timeZone, adjustForTimeZone: true, disambiguation: "compatible" },
    ),
  );

const WEEKDAY_NUMBERS: Record<Weekday, number> = {
  sunday: 0,
  monday: 1,
  tuesday: 2,
  wednesday: 3,
  thursday: 4,
  friday: 5,
  saturday: 6,
};

export const parseDateIso = (dateStr: string): { year: number; month: number; day: number } => {
  const parts = dateStr.split("-");
  const year = parseInt(parts[0] ?? "0", 10);
  const month = parseInt(parts[1] ?? "0", 10);
  const day = parseInt(parts[2] ?? "0", 10);
  return { year, month, day };
};

export const parseSendTime = (sendTime: SendTime): { hour: number; minute: number } => {
  const parts = sendTime.split(":");
  const hour = parseInt(parts[0] ?? "0", 10);
  const minute = parseInt(parts[1] ?? "0", 10);
  return { hour, minute };
};

const utcDate = (year: number, month: number, day: number) => DateTime.makeUnsafe({ year, month, day });

const nextWeekdayOn = (from: DateTime.Utc, targetWeekday: Weekday, includeToday: boolean): DateTime.Utc => {
  const currentWeekday = DateTime.getPartUtc(from, "weekDay");
  const targetDayNum = WEEKDAY_NUMBERS[targetWeekday];

  let daysAhead = targetDayNum - currentWeekday;
  if (daysAhead < 0 || (daysAhead === 0 && !includeToday)) {
    daysAhead += 7;
  }
  return DateTime.add(from, { days: daysAhead });
};

export const nextWeekdayDate = (
  fromYear: number,
  fromMonth: number,
  fromDay: number,
  targetWeekday: Weekday,
  includeToday: boolean,
): string =>
  DateTime.formatIsoDateUtc(
    nextWeekdayOn(utcDate(fromYear, fromMonth, fromDay), targetWeekday, includeToday),
  );

export const nextEightWeeksCadenceDates = (
  nowMs: number,
  weekday: Weekday,
  timeZone: string,
): ReadonlyArray<string> => {
  const { year, month, day } = teamToday(nowMs, timeZone);
  const first = nextWeekdayOn(utcDate(year, month, day), weekday, true);

  const result: Array<string> = [];
  for (let i = 0; i < 8; i++) {
    result.push(DateTime.formatIsoDateUtc(DateTime.add(first, { days: i * 7 })));
  }
  return result;
};

export const calculateRoundInstants = (
  targetDateStr: string,
  sendTime: SendTime,
  memberTimeZones: ReadonlyArray<string>,
  fallbackTimeZone: string,
  answerWindowDays: number,
): {
  readonly openInstant: number;
  readonly latestSendInstant: number;
  readonly closeInstant: number;
  readonly sends: ReadonlyArray<{ readonly timeZone: string; readonly sendAt: number }>;
} => {
  const { year, month, day } = parseDateIso(targetDateStr);
  const { hour, minute } = parseSendTime(sendTime);

  const timeZonesToUse = memberTimeZones.length > 0 ? memberTimeZones : [fallbackTimeZone];

  const sends = timeZonesToUse.map((tz) => ({
    timeZone: tz,
    sendAt: localToUtc(year, month, day, hour, minute, tz),
  }));

  const sendTimes = sends.map((s) => s.sendAt);
  const openInstant = Math.min(...sendTimes);
  const latestSendInstant = Math.max(...sendTimes);
  const closeInstant = latestSendInstant + answerWindowDays * 24 * 3600_000;

  return {
    openInstant,
    latestSendInstant,
    closeInstant,
    sends,
  };
};

export interface RoundSlotInput {
  readonly now: number;
  readonly weekday: Weekday;
  readonly sendTime: SendTime;
  readonly teamTimeZone: string;
  readonly memberTimeZones: ReadonlyArray<string>;
  readonly answerWindowDays: number;
  readonly unavailableDates: ReadonlySet<string>;
}

export interface RoundSlot {
  readonly plannedOpenDate: string;
  readonly instants: ReturnType<typeof calculateRoundInstants>;
}

const addDays = (dateIso: string, days: number): string => {
  const { year, month, day } = parseDateIso(dateIso);
  return DateTime.formatIsoDateUtc(DateTime.add(utcDate(year, month, day), { days }));
};

const teamToday = (now: number, timeZone: string) => {
  const { year, month, day } = DateTime.toParts(DateTime.makeZonedUnsafe(now, { timeZone }));
  return { year, month, day };
};

export const nextRoundSlot = (input: RoundSlotInput): RoundSlot => {
  const slotOn = (plannedOpenDate: string): RoundSlot => ({
    plannedOpenDate,
    instants: calculateRoundInstants(
      plannedOpenDate,
      input.sendTime,
      input.memberTimeZones,
      input.teamTimeZone,
      input.answerWindowDays,
    ),
  });

  const today = teamToday(input.now, input.teamTimeZone);
  let slot = slotOn(nextWeekdayDate(today.year, today.month, today.day, input.weekday, true));
  while (slot.instants.openInstant <= input.now || input.unavailableDates.has(slot.plannedOpenDate)) {
    slot = slotOn(addDays(slot.plannedOpenDate, 7));
  }
  return slot;
};

export const calculateReminders = (
  sendInstant: number,
  answerWindowDays: number,
  remindersCount: number,
  closeInstant: number,
): ReadonlyArray<number> => {
  if (remindersCount <= 0) return [];

  const candidates: Array<number> = [];
  if (answerWindowDays === 1) {
    candidates.push(sendInstant + 6 * 3600_000);
  } else if (remindersCount === 1) {
    candidates.push(sendInstant + (answerWindowDays - 1) * 24 * 3600_000);
  } else if (remindersCount === 2) {
    candidates.push(sendInstant + 1 * 24 * 3600_000);
    const dayWMinusOne = sendInstant + (answerWindowDays - 1) * 24 * 3600_000;
    if (dayWMinusOne !== candidates[0]) {
      candidates.push(dayWMinusOne);
    }
  }

  const cutoff = closeInstant - 2 * 3600_000;
  return candidates.filter((time) => time < cutoff);
};

export const calculateResultsReadyDeliveryTime = (nowMs: number, timeZone: string): number => {
  const { year, month, day, hour } = DateTime.toParts(DateTime.makeZonedUnsafe(nowMs, { timeZone }));

  if (hour >= 8 && hour < 20) {
    return nowMs;
  }

  if (hour < 8) {
    return localToUtc(year, month, day, 8, 0, timeZone);
  }

  const tomorrow = DateTime.toPartsUtc(DateTime.add(utcDate(year, month, day), { days: 1 }));
  return localToUtc(tomorrow.year, tomorrow.month, tomorrow.day, 8, 0, timeZone);
};

export type RoundCommand =
  | {
      readonly _tag: "SkipWeek";
      readonly teamId: TeamId;
      readonly pulseId: PulseId;
      readonly plannedOpenDate: string;
    }
  | {
      readonly _tag: "UnskipWeek";
