  | { readonly _tag: "Rejected"; readonly rejection: PulseRejection }
  | {
      readonly _tag: "Allowed";

      readonly person: PersonRecord;
      readonly pulse: PulseRecord;
    };

export const decideTestSend = (
  directory: DirectoryState,
  state: PulseState,
